// lib/features/institution/serial_join_page.dart
// The real "Join My Organization" flow.
//
// Old behaviour (school_code_page.dart): type in a shared school code,
// anyone who knew it could join, and the account itself never "morphed" —
// same app, same colors, just a different content filter underneath.
//
// New behaviour: each student holds a single, pre-issued serial number
// (one per paid seat, generated by SerialRepository.generateBatch when the
// school signs on). Entering it:
//   1. Verifies the serial and shows the institution's real branding —
//      logo, name, colors — right here, before any account exists. This
//      is the "morph" moment: the screen visibly becomes the school's.
//   2. Lets the student create their account under that identity. On
//      submit, the serial is atomically claimed — it can never be reused,
//      shared, or transferred to another device or account.

import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import '../../theme/app_theme.dart';
import '../../models/institution.dart';
import '../../models/serial_number.dart';
import '../../repositories/serial_repository.dart';
import '../../services/auth_service.dart';
import '../../widgets/widgets.dart';
import '../../widgets/app_background.dart';

class SerialJoinPage extends StatefulWidget {
  const SerialJoinPage({super.key});
  @override
  State<SerialJoinPage> createState() => _SerialJoinPageState();
}

class _SerialJoinPageState extends State<SerialJoinPage> {
  final _serialCtrl = TextEditingController();
  bool _verifying = false;
  String? _verifyError;

  SerialNumber? _serial;
  Institution? _institution;

  @override
  void dispose() {
    _serialCtrl.dispose();
    super.dispose();
  }

  Future<void> _verify() async {
    final code = _serialCtrl.text.trim();
    if (code.isEmpty) return;
    setState(() { _verifying = true; _verifyError = null; });

    final result = await SerialRepository.instance.preview(code);
    if (!mounted) return;

    switch (result) {
      case Success(:final value):
        setState(() {
          _serial = value.serial;
          _institution = value.institution;
          _verifying = false;
        });
      case Failure(:final message):
        setState(() { _verifyError = message; _verifying = false; });
    }
  }

  void _startOver() {
    setState(() {
      _serial = null;
      _institution = null;
      _verifyError = null;
      _serialCtrl.clear();
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: C.bg,
      body: AppBackground(child: SafeArea(
        child: AnimatedSwitcher(
          duration: const Duration(milliseconds: 350),
          child: _institution == null
              ? _SerialEntryStep(
                  key: const ValueKey('entry'),
                  controller: _serialCtrl,
                  loading: _verifying,
                  error: _verifyError,
                  onSubmit: _verify,
                )
              : _BrandedAccountStep(
                  key: const ValueKey('account'),
                  serial: _serial!,
                  institution: _institution!,
                  onBack: _startOver,
                ),
        ),
      )),
    );
  }
}

// ── Step 1: enter the serial number ─────────────────────────────────────

class _SerialEntryStep extends StatelessWidget {
  final TextEditingController controller;
  final bool loading;
  final String? error;
  final VoidCallback onSubmit;
  const _SerialEntryStep({
    super.key, required this.controller, required this.loading,
    required this.error, required this.onSubmit,
  });

  @override
  Widget build(BuildContext context) {
    return Stack(children: [
      Center(
        child: SingleChildScrollView(
          padding: const EdgeInsets.symmetric(horizontal: 28, vertical: 32),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Container(
              width: 88, height: 88,
              decoration: BoxDecoration(
                gradient: const LinearGradient(
                  colors: [C.navy, C.navy2],
                  begin: Alignment.topLeft, end: Alignment.bottomRight),
                borderRadius: BorderRadius.circular(Rad.xl),
                boxShadow: Shad.md,
              ),
              child: const Icon(Icons.qr_code_2_rounded, size: 44, color: Colors.white),
            ),
            const SizedBox(height: 28),
            Text('Join Your Organization',
                style: GoogleFonts.sora(fontSize: 26, fontWeight: FontWeight.w800, color: C.txt)),
            const SizedBox(height: 8),
            Text(
              "Enter the personal serial number your school gave you when "
              "you paid your fees. It's yours alone — no one else can use it.",
              textAlign: TextAlign.center,
              style: GoogleFonts.inter(fontSize: 14, color: C.txt2, height: 1.4),
            ),
            const SizedBox(height: 40),

            TextField(
              controller: controller,
              textCapitalization: TextCapitalization.characters,
              textAlign: TextAlign.center,
              style: GoogleFonts.sora(fontSize: 18, fontWeight: FontWeight.w700,
                  letterSpacing: 2, color: C.txt),
              onSubmitted: (_) => onSubmit(),
              decoration: InputDecoration(
                hintText: 'SM-XXXXXX',
                hintStyle: GoogleFonts.sora(fontSize: 16, letterSpacing: 2,
                    color: C.muted, fontWeight: FontWeight.w600),
                prefixIcon: const Icon(Icons.confirmation_number_outlined, color: C.muted),
                filled: true, fillColor: C.surf,
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(Rad.md),
                    borderSide: const BorderSide(color: C.bdr)),
                enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(Rad.md),
                    borderSide: const BorderSide(color: C.bdr)),
                focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(Rad.md),
                    borderSide: const BorderSide(color: C.primary, width: 2)),
                contentPadding: const EdgeInsets.symmetric(vertical: 18),
              ),
            ),

            if (error != null) ...[
              const SizedBox(height: 12),
              Container(
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(color: C.redb,
                    borderRadius: BorderRadius.circular(Rad.sm),
                    border: Border.all(color: C.red.withValues(alpha: .3))),
                child: Row(children: [
                  const Icon(Icons.error_outline, color: C.red, size: 16),
                  const SizedBox(width: 8),
                  Expanded(child: Text(error!, style: GoogleFonts.inter(color: C.red, fontSize: 13))),
                ]),
              ),
            ],
            const SizedBox(height: 20),

            SizedBox(
              width: double.infinity, height: 54,
              child: ElevatedButton(
                onPressed: loading ? null : onSubmit,
                style: ElevatedButton.styleFrom(
                  backgroundColor: C.navy, foregroundColor: Colors.white,
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(Rad.md)),
                  elevation: 0,
                ),
                child: loading
                    ? const SizedBox(width: 20, height: 20,
                        child: CircularProgressIndicator(strokeWidth: 2.5, color: Colors.white))
                    : Text('Continue', style: GoogleFonts.sora(fontSize: 16, fontWeight: FontWeight.w700)),
              ),
            ),
            const SizedBox(height: 28),

            Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: C.goldp, borderRadius: BorderRadius.circular(Rad.sm),
                border: Border.all(color: C.gold.withValues(alpha: .3)),
              ),
              child: Row(children: [
                const Icon(Icons.info_outline_rounded, color: C.gold, size: 16),
                const SizedBox(width: 8),
                Expanded(child: Text(
                    "Don't have a serial number? It's issued once your school "
                    "fees are paid — ask your school's administration.",
                    style: GoogleFonts.inter(fontSize: 12, color: C.navy3))),
              ]),
            ),
          ]),
        ),
      ),
      if (Navigator.of(context).canPop())
        Positioned(top: 4, left: 4, child: IconButton(
          icon: const Icon(Icons.arrow_back_rounded, color: C.txt2),
          onPressed: () => Navigator.of(context).pop(),
        )),
    ]);
  }
}

// ── Step 2: the app "morphs" — branded preview + account creation ───────

class _BrandedAccountStep extends StatefulWidget {
  final SerialNumber serial;
  final Institution institution;
  final VoidCallback onBack;
  const _BrandedAccountStep({
    super.key, required this.serial, required this.institution, required this.onBack,
  });

  @override
  State<_BrandedAccountStep> createState() => _BrandedAccountStepState();
}

class _BrandedAccountStepState extends State<_BrandedAccountStep> {
  final _formKey = GlobalKey<FormState>();
  final _nameCtrl = TextEditingController();
  final _emailCtrl = TextEditingController();
  final _passwordCtrl = TextEditingController();
  bool _loading = false;
  bool _obscure = true;
  String? _error;

  @override
  void dispose() {
    _nameCtrl.dispose(); _emailCtrl.dispose(); _passwordCtrl.dispose();
    super.dispose();
  }

  Future<void> _submit() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() { _loading = true; _error = null; });
    try {
      await AuthService.instance.claimSerialAndCreateAccount(
        serialCode: widget.serial.code,
        institutionId: widget.institution.institutionId,
        name: _nameCtrl.text.trim(),
        email: _emailCtrl.text.trim(),
        password: _passwordCtrl.text,
      );
      if (!mounted) return;
      // Root AppRouter picks up the newly-linked account and swaps to the
      // institution's own splash + HomeShell automatically.
      Navigator.of(context).popUntil((r) => r.isFirst);
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _error = e.toString().replaceFirst('Exception: ', '');
        _loading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final inst = widget.institution;
    return SingleChildScrollView(
      padding: const EdgeInsets.fromLTRB(20, 8, 20, 32),
      child: Form(
        key: _formKey,
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            IconButton(icon: const Icon(Icons.arrow_back_rounded, color: C.txt2), onPressed: widget.onBack),
          ]),
          // ── Branded preview banner — this is where the app "becomes" the
          // school: real logo, real name, real colors, right in the flow. ──
          Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 22),
            decoration: BoxDecoration(
              gradient: LinearGradient(colors: [inst.primary, inst.secondary]),
              borderRadius: BorderRadius.circular(Rad.lg),
              boxShadow: Shad.md,
            ),
            child: Row(children: [
              Container(
                width: 56, height: 56,
                decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(14)),
                child: inst.logoUrl != null
                    ? ClipRRect(borderRadius: BorderRadius.circular(14),
                        child: Image.network(inst.logoUrl!, fit: BoxFit.cover,
                            errorBuilder: (_, __, ___) => _logoFallback(inst)))
                    : _logoFallback(inst),
              ),
              const SizedBox(width: 16),
              Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(inst.schoolName,
                    style: GoogleFonts.sora(fontSize: 19, fontWeight: FontWeight.w800, color: Colors.white),
                    overflow: TextOverflow.ellipsis),
                const SizedBox(height: 2),
                Text('Powered by Academia',
                    style: GoogleFonts.inter(fontSize: 11, color: Colors.white70)),
              ])),
              const Icon(Icons.check_circle_rounded, color: Colors.white, size: 22),
            ]),
          ),
          const SizedBox(height: 10),
          Text('Serial ${widget.serial.code} verified — this seat is yours.',
              style: GoogleFonts.inter(fontSize: 12, color: C.txt2)),
          const SizedBox(height: 24),

          Text('Create your account',
              style: GoogleFonts.sora(fontSize: 20, fontWeight: FontWeight.w800, color: C.txt)),
          const SizedBox(height: 6),
          Text('This account is permanently linked to ${inst.schoolName} — '
               'once created, this serial number can never be used again.',
              style: GoogleFonts.inter(fontSize: 13, color: C.txt2, height: 1.4)),
          const SizedBox(height: 22),

          if (_error != null) ...[
            Container(
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(color: C.redb, borderRadius: BorderRadius.circular(Rad.sm),
                  border: Border.all(color: C.red.withValues(alpha: .3))),
              child: Row(children: [
                const Icon(Icons.error_outline, color: C.red, size: 16),
                const SizedBox(width: 8),
                Expanded(child: Text(_error!, style: GoogleFonts.inter(color: C.red, fontSize: 13))),
              ]),
            ),
            const SizedBox(height: 16),
          ],

          _Field(controller: _nameCtrl, hint: 'Full name', icon: Icons.person_outline_rounded,
              validator: (v) => (v == null || v.trim().length < 2) ? 'Enter your name' : null),
          const SizedBox(height: 12),
          _Field(controller: _emailCtrl, hint: 'Email address', icon: Icons.email_outlined,
              keyboardType: TextInputType.emailAddress,
              validator: (v) => (v == null || !v.contains('@')) ? 'Enter a valid email' : null),
          const SizedBox(height: 12),
          _Field(
            controller: _passwordCtrl, hint: 'Password', icon: Icons.lock_outline_rounded,
            obscureText: _obscure, onSubmitted: (_) => _submit(),
            validator: (v) => (v == null || v.length < 6) ? 'At least 6 characters' : null,
            suffix: IconButton(
              icon: Icon(_obscure ? Icons.visibility_off_rounded : Icons.visibility_rounded,
                  color: C.muted, size: 18),
              onPressed: () => setState(() => _obscure = !_obscure),
            ),
          ),
          const SizedBox(height: 26),

          SizedBox(
            width: double.infinity, height: 54,
            child: ElevatedButton(
              onPressed: _loading ? null : _submit,
              style: ElevatedButton.styleFrom(
                backgroundColor: inst.primary, foregroundColor: Colors.white,
                shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(Rad.md)),
                elevation: 0,
              ),
              child: _loading
                  ? const SizedBox(width: 20, height: 20,
                      child: CircularProgressIndicator(strokeWidth: 2.5, color: Colors.white))
                  : Text('Create My ${inst.schoolName} Account',
                      textAlign: TextAlign.center,
                      style: GoogleFonts.sora(fontSize: 15, fontWeight: FontWeight.w700)),
            ),
          ),
        ]),
      ),
    );
  }

  Widget _logoFallback(Institution inst) => Center(
      child: Text(inst.schoolName.isNotEmpty ? inst.schoolName[0].toUpperCase() : 'A',
          style: GoogleFonts.sora(fontSize: 24, fontWeight: FontWeight.w800, color: inst.primary)));
}

class _Field extends StatelessWidget {
  final TextEditingController controller;
  final String hint;
  final IconData icon;
  final bool obscureText;
  final TextInputType? keyboardType;
  final Widget? suffix;
  final String? Function(String?)? validator;
  final ValueChanged<String>? onSubmitted;
  const _Field({
    required this.controller, required this.hint, required this.icon,
    this.obscureText = false, this.keyboardType, this.suffix,
    this.validator, this.onSubmitted,
  });

  @override
  Widget build(BuildContext context) {
    return TextFormField(
      controller: controller,
      obscureText: obscureText,
      keyboardType: keyboardType,
      onFieldSubmitted: onSubmitted,
      validator: validator,
      style: GoogleFonts.inter(fontSize: 14, color: C.txt),
      decoration: InputDecoration(
        hintText: hint,
        hintStyle: GoogleFonts.inter(fontSize: 14, color: C.muted),
        prefixIcon: Icon(icon, color: C.muted, size: 20),
        suffixIcon: suffix,
        filled: true, fillColor: C.surf,
        border: OutlineInputBorder(borderRadius: BorderRadius.circular(Rad.md), borderSide: const BorderSide(color: C.bdr)),
        enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(Rad.md), borderSide: const BorderSide(color: C.bdr)),
        focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(Rad.md), borderSide: const BorderSide(color: C.primary, width: 2)),
        errorBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(Rad.md), borderSide: const BorderSide(color: C.red)),
        focusedErrorBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(Rad.md), borderSide: const BorderSide(color: C.red, width: 2)),
        contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 16),
      ),
    );
  }
}
